-- M0: moves and expenses, with row-level security (RLS).
-- PRD: MOVE-1, EXP-4, EXP-5. Architecture: docs/architecture.md §5–6.
--
-- Conventions
--   * UUID primary keys, generated by clients so rows can be created offline.
--   * Money as integer cents + ISO 4217 currency code. Never floating point.
--   * created_at / updated_at / deleted_at on every row (soft delete so deletions sync).
--   * Every user-owned table carries user_id and is protected by RLS.

-- ---------------------------------------------------------------------------
-- Shared helpers
-- ---------------------------------------------------------------------------

create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create type public.package_type as enum ('lump_sum', 'itemized', 'vendor_managed', 'hybrid');
create type public.payer as enum ('me', 'employer', 'vendor_direct');
create type public.extraction_source as enum ('manual', 'on_device', 'cloud');

-- ---------------------------------------------------------------------------
-- moves
-- ---------------------------------------------------------------------------

create table public.moves (
  id                  uuid primary key default gen_random_uuid(),
  user_id             uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name                text not null check (char_length(name) between 1 and 200),
  origin_address      text check (char_length(origin_address) <= 500),
  destination_address text check (char_length(destination_address) <= 500),
  move_date           date,
  start_date          date,
  is_active           boolean not null default true,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  deleted_at          timestamptz,

  -- Lets child tables use a composite foreign key so a child row can only point
  -- at a move owned by the same user (enforced even if a client lies about user_id).
  unique (id, user_id)
);

comment on table public.moves is 'One relocation (PRD MOVE-1).';

create index moves_user_id_idx on public.moves (user_id);

create trigger moves_set_updated_at
  before update on public.moves
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- expenses
-- ---------------------------------------------------------------------------

create table public.expenses (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null default auth.uid(),
  move_id           uuid not null,
  amount_cents      bigint not null check (amount_cents >= 0),
  currency          char(3) not null default 'USD' check (currency ~ '^[A-Z]{3}$'),
  occurred_on       date not null,
  merchant          text not null default '' check (char_length(merchant) <= 200),
  category_id       text not null check (category_id ~ '^[a-z0-9_]{1,50}$'),
  payer             public.payer not null default 'me',
  missing_receipt   boolean not null default false,
  tax_tags          text[] not null default '{}',
  extraction_source public.extraction_source not null default 'manual',
  notes             text check (char_length(notes) <= 2000),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,

  foreign key (move_id, user_id) references public.moves (id, user_id) on delete cascade
);

comment on table public.expenses is 'Money spent on a move (PRD EXP-*). payer decides allowance vs. clawback basis.';
comment on column public.expenses.payer is 'me = uses allowance; employer / vendor_direct = counts toward clawback relocation costs only.';

create index expenses_user_id_idx on public.expenses (user_id);
create index expenses_move_id_occurred_on_idx on public.expenses (move_id, occurred_on);

create trigger expenses_set_updated_at
  before update on public.expenses
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Access control
-- ---------------------------------------------------------------------------
-- Signed-out (anon) clients get nothing. Signed-in users get only their own rows.
-- `(select auth.uid())` is evaluated once per statement instead of once per row.

revoke all on public.moves, public.expenses from anon;

alter table public.moves enable row level security;
alter table public.expenses enable row level security;

create policy "moves: owner can read"   on public.moves for select to authenticated using ((select auth.uid()) = user_id);
create policy "moves: owner can insert" on public.moves for insert to authenticated with check ((select auth.uid()) = user_id);
create policy "moves: owner can update" on public.moves for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "moves: owner can delete" on public.moves for delete to authenticated using ((select auth.uid()) = user_id);

create policy "expenses: owner can read"   on public.expenses for select to authenticated using ((select auth.uid()) = user_id);
create policy "expenses: owner can insert" on public.expenses for insert to authenticated with check ((select auth.uid()) = user_id);
create policy "expenses: owner can update" on public.expenses for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "expenses: owner can delete" on public.expenses for delete to authenticated using ((select auth.uid()) = user_id);
